# owner: platform
"""Plain text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.attendance import days_missed

def _check_marks(student, marks):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} does not "
                f"belong to {student.student_id}"
            )

def _compose(student, dates):
    count = len(dates)
    unit = "day" if count == 1 else "days"
    listed = ", ".join(item.isoformat() for item in dates)
    return (
        f"{student.first_name} {student.last_name} missed "
        f"{count} {unit} of school: {listed}."
    )

# ---
def absence_notice(student: Student, marks) -> str:
    marks = list(marks)
    _check_marks(student, marks)
    dates = days_missed(marks)
    if not dates:
        raise ValueError("no absences to write about")
    return _compose(student, dates)
